import type { VenueRow } from "@/state/venueStore";
import { searchVenues } from "@/state/venueStore";
import { getSyncState } from "@/chain/sync";

/**
 * The MAP render seed (app/src/data/venue_render.json — GENERATED by
 * tools/dys_venue_render.py from the s32 atlas + name probe; never
 * hand-edit). TWO framings ship (kb §9, the session-32 atlas findings):
 * CANON (ln + f: fold-fraction ±180° lon, |lat|/pole lat — the onchain
 * distribution's own space, uniform fill) and LEGACY (lon/lat degrees =
 * the predecessor's equirect band-as-longitude globe — diagonal-bunching,
 * kept as a toggle). The latitude scale is exact: pole = Meridians[88]/333.
 */

export interface RenderRow {
  /** venue (QING) address (lowercase) */
  a: string;
  /** onchain-probed name (empty = nameless onchain) */
  n: string;
  /** symbol */
  s: string;
  /** folded band fraction (-1..1) — the venue's longitude within its band */
  f: number;
  /** HECKE meridian band 0..89 */
  band: number;
  /** creation block */
  blk: number;
  /** south-flip (band-89 mirror) — false = the north hemisphere in CANON */
  south: boolean;
  /** system-flagged: the first QING (Phobos), from config — never hand-listed */
  sys: boolean;
  /** waat (decimal string, s32-exact) */
  w: string;
  /** HECKE longitude degrees [-180,180] — the LEGACY framing */
  lon: number;
  /** HECKE latitude degrees [-90,90] — the LEGACY framing */
  lat: number;
  /** |latitude| ÷ pole, 0..1 (kb §9 canonical; sign comes from `south`) */
  ln: number;
  /**
   * The wrapped ASSET address (lowercase; the NewQing event's Integrative —
   * the ONE asset→QING link the chain offers, MAP exposes no getter). Rides
   * the seed since session-73 (the census backfill) + the sync engine's
   * enrichment; optional because pre-73 cached rows may lack it.
   */
  asset?: string | undefined;
}

export interface RenderDoc {
  _meta: {
    generated: string;
    source: string;
    count: number;
    note: string;
    /** the 90 meridian constants (decimal strings) — verbatim from the s32 atlas (session-67: live-venue synthesis) */
    meridians: string[];
    /** pole = Meridians[88]÷333 (decimal string, kb §9 EXACT) */
    pole: string;
  };
  venues: RenderRow[];
}

const LOADERS = import.meta.glob("../data/venue_render.json") as Record<
  string,
  () => Promise<{ default: RenderDoc }>
>;

let docPromise: Promise<RenderRow[]> | null = null;

export function loadRenderRows(): Promise<RenderRow[]> {
  if (!docPromise) {
    const key = Object.keys(LOADERS)[0];
    if (!key) return Promise.reject(new Error("render seed not found"));
    docPromise = LOADERS[key]!().then((m) => m.default.venues);
  }
  return docPromise;
}

/** the app-global store's VenueRow subset (lat = folded f, seed semantics) */
export function renderRowAsVenueRow(r: RenderRow): VenueRow {
  return { a: r.a, n: r.n, s: r.s, lat: r.f, band: r.band, blk: r.blk };
}

// ---- session-73: the asset→QING index (the agent world-model round) ----
// MAP exposes NO asset→QING getter (kb §4), but every QING creation emits
// NewQing(Qing, Integrative, Waat) — so the census seed + the sync engine's
// catch-up rows ARE the index. This is how a pre-app account (an aged
// transfer) learns its home QING: get_state resolves it from here, the
// captured-at-create record stays the fast path.

/** seed rows + the sync engine's caught-up rows, address-deduped (seed wins —
 * the mergeByAddress law) */
export async function venueCensusRows(): Promise<RenderRow[]> {
  const seed = await loadRenderRows();
  const live = getSyncState().qingRows;
  const seen = new Set(seed.map((r) => r.a));
  const out = [...seed];
  for (const r of live) {
    if (!seen.has(r.a)) {
      seen.add(r.a);
      out.push(r);
    }
  }
  return out;
}

/**
 * The QING wrapping a given asset (e.g. your LAU) from the census — null
 * when the asset has none (a legitimate claim target) or the rows carry no
 * asset field yet (pre-73 caches). `rows` is a test seam.
 */
export async function qingForAsset(asset: string, rows?: RenderRow[]): Promise<RenderRow | null> {
  const all = rows ?? (await venueCensusRows());
  const a = asset.toLowerCase();
  for (const r of all) {
    if (r.asset !== undefined && r.asset.toLowerCase() === a) return r;
  }
  return null;
}

/** the census search (the sidebar's searchVenues over seed ∪ live) */
export interface CensusHit extends VenueRow {
  asset?: string | undefined;
  live: boolean;
}
export async function searchVenueCensus(query: string, limit = 24): Promise<{ rows: CensusHit[]; total: number }> {
  const all = await venueCensusRows();
  const seedAddrs = new Set((await loadRenderRows()).map((r) => r.a));
  const asVenue: CensusHit[] = all.map((r) => ({ a: r.a, n: r.n, s: r.s, lat: r.f, band: r.band, blk: r.blk, asset: r.asset, live: !seedAddrs.has(r.a) }));
  const { rows, total } = searchVenues(asVenue, query, limit);
  return { rows, total };
}

// ---- session-67: LIVE-venue coordinate synthesis (kb §9, the tool's math) ----

/** the meridian table + pole, shipped verbatim in the render seed's meta */
export interface AtlasMath {
  meridians: bigint[];
  pole: bigint;
}

let mathPromise: Promise<AtlasMath> | null = null;

export function loadAtlasMath(): Promise<AtlasMath> {
  if (!mathPromise) {
    const key = Object.keys(LOADERS)[0];
    if (!key) return Promise.reject(new Error("render seed not found"));
    mathPromise = LOADERS[key]!().then((m) => {
      const { meridians, pole } = m.default._meta;
      const parsed = meridians.map((s) => BigInt(s));
      const p = BigInt(pole);
      if (parsed.length !== 90 || p <= 0n) throw new Error("atlas meta malformed (meridians/pole)");
      return { meridians: parsed, pole: p };
    });
  }
  return mathPromise;
}

/** band = the first meridian ≥ waat (else 89) — the tool's meridian_of */
export function meridianOf(waat: bigint, meridians: readonly bigint[]): number {
  for (let i = 0; i < meridians.length; i++) {
    if (meridians[i]! >= waat) return i;
  }
  return meridians.length - 1;
}

/** the derived coordinate fields every RenderRow carries (kb §9 semantics) */
export interface HeckeCoords {
  /** folded band fraction (-1..1) */
  f: number;
  /** effective meridian band */
  band: number;
  /** band-89 north flip */
  south: boolean;
  /** legacy equirect longitude degrees [-180,180] */
  lon: number;
  /** legacy equirect latitude degrees [-90,90] */
  lat: number;
  /** CANON |latitude|/pole (0..1) */
  ln: number;
}

/**
 * The EXACT integer replication of HECKE.Compliment's fold (kb §9; mirrors
 * tools/dys_venue_render.py — the self-check test pins them together):
 * band = meridian containing waat; the flip mirrors band-89 waats north
 * (waat' = Meridians[89] − waat); the fold fraction is longitude ÷ band
 * half-width for BOTH flip states; CANON ln = |Latitude|/pole LINEAR.
 * Inputs are the RAW Compliment ints ( Longitude, Latitude).
 */
export function heckeCoords(waat: bigint, lonRaw: bigint, latRaw: bigint, m: AtlasMath): HeckeCoords {
  const meridians = m.meridians;
  const mer89 = meridians[89]!;
  const mer = meridianOf(waat, meridians);
  const flipped = mer === 89 && latRaw > 0n;
  const effWaat = flipped ? mer89 - waat : waat;
  const effMer = flipped ? meridianOf(effWaat, meridians) : mer;
  const bandStart = effMer > 0 ? meridians[effMer - 1]! : 0n;
  const bandEnd = meridians[effMer]!;
  const bandWidth = bandEnd - bandStart;
  const halfWidth = bandWidth / 2n;
  let f = halfWidth > 0n ? Number(lonRaw) / Number(halfWidth) : 0;
  f = Math.max(-1, Math.min(1, f));

  let lonDeg = effMer * 4 + f * 2;
  lonDeg = ((lonDeg % 360) + 360) % 360;
  if (lonDeg > 180) lonDeg -= 360;

  let latDeg = (Number(latRaw) / Number(m.pole)) * 90;
  if (flipped) latDeg = -latDeg;
  latDeg = Math.max(-90, Math.min(90, latDeg));

  const ln = Math.min(1, Math.abs(Number(latRaw)) / Number(m.pole));
  return { f, band: effMer, south: flipped, lon: lonDeg, lat: latDeg, ln };
}

/** merge live metadata + computed coords into a full canvas RenderRow */
export function synthesizeRenderRow(
  base: { a: string; n: string; s: string; blk: number },
  coords: HeckeCoords,
  waat: string
): RenderRow {
  return {
    a: base.a.toLowerCase(),
    n: base.n,
    s: base.s,
    f: coords.f,
    band: coords.band,
    blk: base.blk,
    south: coords.south,
    sys: false,
    w: waat,
    lon: coords.lon,
    lat: coords.lat,
    ln: coords.ln,
  };
}

/**
 * Display mass — the predecessor QingMap's visual idiom (entropySim): a
 * deterministic hash of the address, Phobos heavier. VISUAL WEIGHT ONLY —
 * this is not the venue's onchain Entropy; the live Entropy() read renders
 * in the venue panel.
 */
export function displayMass(r: RenderRow): number {
  if (r.sys) return 100;
  return (parseInt(r.a.slice(-4), 16) % 30) + 10;
}

/** stable per-node twinkle phase (deterministic — no Math.random in render) */
export function nodePhase(r: RenderRow): number {
  let h = 0;
  for (let i = 2; i < r.a.length; i++) h = (h * 31 + parseInt(r.a[i]!, 16)) % 6283;
  return (h / 6283) * Math.PI * 2;
}

/** LINEAR projection (the old map's alt coordinate system): waat → flat grid */
export function linearPos(waat: string): { lon: number; lat: number } {
  try {
    const w = BigInt(waat);
    return {
      lon: Number((w / 180n) % 360n) - 180,
      lat: Number(w % 180n) - 90,
    };
  } catch {
    return { lon: 0, lat: 0 };
  }
}
